gQ4(){return"\u0637\u0628\u0627\u0639\u0629 \u0628\u0637\u0627\u0642\u0629 \u0627\u0633\u062a\u0644\u0627\u0645 \u0627\u0644\u0641\u062d\u0635 \u0627\u0644\u0646\u0647\u0627\u0626\u064a \u0628\u0627\u0633\u0645 \u0627\u0644\u0645\u0631\u064a\u0636 \u0648\u0627\u0644\u0637\u0628\u064a\u0628 \u0648\u0631\u0645\u0632 \u0627\u0644\u0627\u0633\u062a\u062c\u0627\u0628\u0629 \u0627\u0644\u0633\u0631\u064a\u0639\u0629 \u0641\u0642\u0637 \u2014 \u0628\u062d\u062c\u0645 \u062b\u0627\u0628\u062a\u060c \u0644\u0644\u0635\u0642\u0647\u0627 \u0639\u0644\u0649 \u0627\u0644\u062d\u0627\u0644\u0629 \u0643\u0645\u0644\u0635\u0642."},
gR2(){return"\u0627\u062d\u062a\u0633\u0627\u0628 \u0627\u0644\u062d\u0627\u0644\u0627\u062a \u0627\u0644\u0645\u064f\u0633\u0644\u064e\u0651\u0645\u0629 \u0641\u0642\u0637 \u0643\u062f\u064a\u0646"},
gR1(){return'\u0627\u0644\u062d\u0627\u0644\u0629 \u0627\u0644\u062a\u064a \u0644\u0645 \u062a\u064f\u0634\u062d\u0646 \u0628\u0639\u062f \u0644\u0646 \u062a\u064f\u062d\u062a\u0633\u0628 \u0636\u0645\u0646 \u0627\u0644\u0645\u0628\u0644\u063a \u0627\u0644\u0645\u0633\u062a\u062d\u0642 \u0639\u0644\u0649 \u0627\u0644\u062f\u0643\u062a\u0648\u0631 \u0641\u064a \u0627\u0644\u0643\u0634\u0641 \u0627\u0644\u0645\u0637\u0628\u0648\u0639\u060c \u0648\u0644\u0646 \u062a\u064f\u062f\u0641\u0639 \u0639\u0628\u0631 \u062f\u0641\u0639\u0629 "\u062d\u0633\u0628 \u0627\u0644\u062f\u0643\u062a\u0648\u0631"\u060c \u0625\u0644\u0649 \u0623\u0646 \u062a\u064f\u0634\u062d\u0646 \u0641\u0639\u0644\u064a\u064b\u0627.'},
gPH(){return"\u0625\u062e\u0641\u0627\u0621 \u0627\u0644\u0637\u0628\u064a\u0628 \u0648\u0627\u0644\u0639\u064a\u0627\u062f\u0629 \u0641\u064a \u0645\u0644\u0635\u0642 \u0627\u0644\u062d\u0627\u0644\u0629"},
gPG(){return"\u0644\u0627 \u064a\u064f\u0637\u0628\u0639 \u0627\u0633\u0645 \u0627\u0644\u0639\u064a\u0627\u062f\u0629 \u0648\u0627\u0644\u0637\u0628\u064a\u0628 \u0648\u0645\u0634\u063a\u0651\u0644 \u0627\u0644\u0645\u0627\u0633\u062d \u0639\u0644\u0649 \u0645\u0644\u0635\u0642 \u0627\u0644\u062d\u0627\u0644\u0629 (\u0627\u0644\u0630\u064a \u064a\u0631\u0627\u0641\u0642 \u0627\u0644\u0639\u0645\u0644)\u060c \u062d\u062a\u0649 \u0644\u0627 \u064a\u0639\u0631\u0641 \u0627\u0644\u0641\u0646\u064a\u0648\u0646 \u0644\u0645\u0646 \u062a\u0639\u0648\u062f \u0627\u0644\u062d\u0627\u0644\u0629. \u062a\u0628\u0642\u0649 \u0627\u0644\u0641\u0648\u0627\u062a\u064a\u0631 \u0648\u0627\u0644\u0643\u0634\u0648\u0641\u0627\u062a \u0648\u062a\u0630\u0643\u0631\u0629 \u0627\u0644\u0627\u0633\u062a\u0644\u0627\u0645 \u062a\u0639\u0631\u0636\u0647\u0627 \u0643\u0627\u0644\u0645\u0639\u062a\u0627\u062f."},
gQw(){return'\u0634\u0631\u064a\u0637 "\u0625\u0639\u0627\u062f\u0629" \u0643\u0628\u064a\u0631 \u0639\u0644\u0649 \u0645\u0644\u0635\u0642 \u0627\u0644\u062d\u0627\u0644\u0629'},
gQv(){return"\u064a\u064f\u0637\u0628\u0639 \u0639\u0644\u0649 \u0645\u0644\u0635\u0642 \u062d\u0627\u0644\u0629 \u0627\u0644\u0625\u0639\u0627\u062f\u0629 \u0634\u0631\u064a\u0637 \u0623\u062d\u0645\u0631 \u0643\u0628\u064a\u0631 \u0645\u0643\u062a\u0648\u0628 \u0639\u0644\u064a\u0647 \u0625\u0639\u0627\u062f\u0629 \u0645\u0639 \u0631\u0642\u0645 \u0627\u0644\u062d\u0627\u0644\u0629 \u0627\u0644\u0623\u0635\u0644\u064a\u0629\u060c \u062d\u062a\u0649 \u064a\u0646\u062a\u0628\u0647 \u0627\u0644\u0641\u0646\u064a\u0648\u0646 \u0623\u0646\u0647\u0627 \u0625\u0639\u0627\u062f\u0629."},
gQP(){return"\u0627\u0644\u0645\u0627\u062f\u0629 \u0641\u064a \u0627\u0644\u0645\u0637\u0628\u0648\u0639\u0627\u062a \u0648\u0628\u0637\u0627\u0642\u0627\u062a \u0627\u0644\u062d\u0627\u0644\u0627\u062a"},
gQO(){return"\u0639\u0646\u062f \u0627\u0644\u0625\u064a\u0642\u0627\u0641: \u0644\u0627 \u062a\u0638\u0647\u0631 \u0627\u0644\u0645\u0627\u062f\u0629 \u0641\u064a \u0645\u0644\u0635\u0642 \u0627\u0644\u062d\u0627\u0644\u0629 \u0648\u0641\u0627\u062a\u0648\u0631\u0629 \u0627\u0644\u0637\u0628\u064a\u0628 \u0648\u0643\u0634\u0641 \u0627\u0644\u062d\u0633\u0627\u0628 \u0648\u0628\u0637\u0627\u0642\u0627\u062a \u0627\u0644\u062d\u0627\u0644\u0627\u062a (\u0642\u0627\u0626\u0645\u0629 \u0627\u0644\u062d\u0627\u0644\u0627\u062a \u0648\u0627\u0644\u0644\u0648\u062d\u0629)."},
gQk(){return"\u062a\u0645 \u062d\u0641\u0638 \u0625\u0639\u062f\u0627\u062f\u0627\u062a \u0627\u0644\u0637\u0628\u0627\u0639\u0629."},
gQp(){return"\u0647\u0630\u0627 \u0627\u0644\u0641\u0631\u0639"},
gOr(){return"\u062d\u0633\u0627\u0628\u064a"},
gOs(){return"\u0628\u0631\u064a\u062f\u0643 \u0627\u0644\u0625\u0644\u0643\u062a\u0631\u0648\u0646\u064a \u0648\u0643\u0644\u0645\u0629 \u0627\u0644\u0645\u0631\u0648\u0631 \u0627\u0644\u062e\u0627\u0635\u0629 \u0628\u062a\u0633\u062c\u064a\u0644 \u0627\u0644\u062f\u062e\u0648\u0644."},
gPL(){return"\u0623\u062f\u062e\u0644 \u0633\u0639\u0631 \u0635\u0631\u0641 \u0635\u062d\u064a\u062d."},
