gQg(){return"\u0627\u0644\u0647\u0627\u062a\u0641"},
gOP(){return"\u0647\u0648\u064a\u0629 \u0627\u0644\u0645\u0633\u062a\u0646\u062f\u0627\u062a \u0627\u0644\u0645\u0637\u0628\u0648\u0639\u0629"},
gOQ(){return"\u062a\u0638\u0647\u0631 \u0641\u064a \u0641\u0627\u062a\u0648\u0631\u0629 \u0627\u0644\u0637\u0628\u064a\u0628\u060c \u0648\u0643\u0644\u0645\u0633\u0629 \u0645\u0645\u064a\u0632\u0629 \u0639\u0644\u0649 \u0628\u0637\u0627\u0642\u0629 \u0627\u0644\u062d\u0627\u0644\u0629 \u0648\u062a\u0630\u0643\u0631\u0629 \u0627\u0644\u062c\u0648\u062f\u0629."},
