QA(a){return"\u0639\u0646\u062f \u0627\u0644\u0625\u064a\u0642\u0627\u0641\u060c \u062a\u064f\u0639\u0631\u0636 \u0628\u0639\u0645\u0644\u0629 "+a+" \u0628\u062f\u0644\u0627\u064b \u0645\u0646 \u0630\u0644\u0643. \u062a\u062d\u062a\u0641\u0638 \u0627\u0644\u062d\u0627\u0644\u0627\u062a \u0627\u0644\u062d\u0627\u0644\u064a\u0629 \u0628\u0633\u0639\u0631 \u0627\u0644\u0635\u0631\u0641 \u0627\u0644\u062e\u0627\u0635 \u0628\u0647\u0627 \u0641\u064a \u0643\u0644\u062a\u0627 \u0627\u0644\u062d\u0627\u0644\u062a\u064a\u0646."},
gP_(){return"\u0628\u0648\u0627\u0628\u0629 \u0627\u0644\u0639\u064a\u0627\u062f\u0629 \u0645\u0641\u0639\u0651\u0644\u0629"},
gP0(){return"\u0623\u0648\u0642\u0641 \u0647\u0630\u0627 \u0627\u0644\u062e\u064a\u0627\u0631 \u0625\u0630\u0627 \u0643\u0627\u0646 \u0647\u0630\u0627 \u0627\u0644\u0645\u062e\u062a\u0628\u0631 \u0644\u0627 \u064a\u0633\u062a\u062e\u062f\u0645 \u062a\u0637\u0628\u064a\u0642 \u0628\u0648\u0627\u0628\u0629 \u0627\u0644\u0637\u0628\u064a\u0628/\u0627\u0644\u0639\u064a\u0627\u062f\u0629 \u0627\u0644\u0645\u0646\u0641\u0635\u0644 \u2014 \u064a\u062e\u0641\u064a \u062c\u0631\u0633 \u0627\u0644\u0625\u0634\u0639\u0627\u0631\u0627\u062a \u0648\u0627\u0644\u0645\u0631\u0627\u0633\u0644\u0629."},
