akP(a,b){return"\u067e\u0632\u06cc\u0634\u06a9\u06d5 \u067e\u06d5\u06cc\u0648\u06d5\u0633\u062a\u06a9\u0631\u0627\u0648\u06d5\u06a9\u0627\u0646: "+a+" \xb7 \u0686\u0627\u062a\u06d5\u06a9\u0627\u0646\u06cc \u062a\u0627\u0642\u06cc\u06af\u06d5 \u06a9\u06d5 \u0626\u0627\u06af\u0627\u062f\u0627\u0631\u06cc \u0648\u06d5\u0631\u062f\u06d5\u06af\u0631\u0646: "+b},
gakM(){return"\u0626\u06d5\u0645 \u0628\u06d5\u0633\u062a\u06d5\u0631\u06d5 \u0628\u06c6 \u067e\u0632\u06cc\u0634\u06a9\u06d5\u06a9\u0627\u0646\u062a \u0628\u0646\u06ce\u0631\u06d5. \xab\u062f\u06d5\u0633\u062a\u067e\u06ce\u06a9\u0631\u062f\u0646\xbb \u062f\u0627\u062f\u06d5\u06af\u0631\u0646 \u0648 \u0698\u0645\u0627\u0631\u06d5\u06cc \u062a\u06d5\u0644\u06d5\u0641\u06c6\u0646\u06d5\u06a9\u06d5\u06cc\u0627\u0646 \u0647\u0627\u0648\u0628\u06d5\u0634 \u062f\u06d5\u06a9\u06d5\u0646\u061b \u0628\u06c6\u062a\u06d5\u06a9\u06d5 \u0628\u06d5\u0648 \u0698\u0645\u0627\u0631\u06d5\u06cc\u06d5\u06cc \u0644\u06d5 \u06a9\u0644\u06cc\u0646\u06cc\u06a9\u06d5\u06a9\u0627\u0646 \u062a\u06c6\u0645\u0627\u0631 \u06a9\u0631\u0627\u0648\u06d5 \u062f\u06d5\u06cc\u0627\u0646\u0646\u0627\u0633\u06ce\u062a\u06d5\u0648\u06d5."},
gakK(){return"\u0628\u06c6 \u0648\u06d5\u0631\u06af\u0631\u062a\u0646\u06cc \u0646\u0627\u0645\u06d5 \u0628\u06c6 \u0647\u06d5\u0631 \u06a9\u06d5\u06cc\u0633\u06ce\u06a9 \u06a9\u06d5 \u067e\u0632\u06cc\u0634\u06a9\u06d5\u06a9\u0627\u0646 \u062f\u06d5\u06cc\u0646\u06ce\u0631\u0646\u060c \u0628\u06c6\u062a\u06d5\u06a9\u06d5 \u0628\u06a9\u06d5\u0631\u06d5\u0648\u06d5 \u0648 \u0628\u0646\u06ce\u0631\u06d5:"},
gakL(){return"\u06a9\u06c6\u062f\u06cc \u0646\u0648\u06ce"},
akD(a){return"\u06a9\u06d5\u06cc\u0633\u06d5\u06a9\u0627\u0646\u06cc \u0628\u06c6\u062a \u0628\u06d5 \u0646\u0627\u0648\u06cc "+a+" \u062a\u06c6\u0645\u0627\u0631 \u062f\u06d5\u06a9\u0631\u06ce\u0646."},
gakG(){return"\u067e\u0686\u0695\u0627\u0646\u062f\u0646\u06cc \u0628\u06c6\u062a"},
gakI(){return"\u0628\u06c6\u062a\u06d5\u06a9\u06d5 \u0628\u067e\u0686\u0695\u06ce\u0646\u0631\u06ce\u062a\u061f"},
akH(a){return a+" \u0686\u06cc\u062a\u0631 \u0648\u06d5\u06b5\u0627\u0645 \u0646\u0627\u062f\u0627\u062a\u06d5\u0648\u06d5 \u0648 \u067e\u06d5\u06cc\u0648\u06d5\u0646\u062f\u06cc \u0647\u06d5\u0645\u0648\u0648 \u067e\u0632\u06cc\u0634\u06a9\u06ce\u06a9 \u062f\u06d5\u0633\u0695\u062f\u0631\u06ce\u062a\u06d5\u0648\u06d5. \u0626\u06d5\u0648 \u06a9\u06d5\u06cc\u0633\u0627\u0646\u06d5\u06cc \u067e\u06ce\u0634\u062a\u0631 \u0646\u06ce\u0631\u062f\u0631\u0627\u0648\u0646 \u0644\u06d5 IQ Labs \u062f\u06d5\u0645\u06ce\u0646\u0646\u06d5\u0648\u06d5."},
gHI(){return"\u0632\u06cc\u0627\u062f\u06a9\u0631\u062f\u0646\u06cc \u067e\u06c6\u0644"},
ga1A(){return"\u0646\u0627\u0648\u06cc \u067e\u06c6\u0644"},
ga1Z(){return"\u062f\u06d5\u0633\u062a\u06a9\u0627\u0631\u06cc\u06a9\u0631\u062f\u0646\u06cc \u067e\u06c6\u0644"},
ga1p(){return"\u067e\u06c6\u0644"},
ga1B(){return"\u0628\u06ce \u067e\u06c6\u0644"},
gHY(){return"\u0628\u06ce \u067e\u06c6\u0644"},
a1U(a){return"\u062f\u06b5\u0646\u06cc\u0627\u06cc\u062a \u0644\u06d5 \u0633\u0695\u06cc\u0646\u06d5\u0648\u06d5\u06cc \u067e\u06c6\u0644\u06cc \xab"+a+"\xbb\u061f"},
ga1T(){return"\u062c\u06c6\u0631\u06d5\u06a9\u0627\u0646\u06cc \u06a9\u06d5\u06cc\u0633\u06cc \u0646\u0627\u0648\u06cc \u062f\u06d5\u0645\u06ce\u0646\u0646\u06d5\u0648\u06d5 \u0648 \u062f\u06d5\u0686\u0646\u06d5 \u0628\u06d5\u0634\u06cc \xab\u0628\u06ce \u067e\u06c6\u0644\xbb."},
