akD(a){return"\u06a9\u06d5\u06cc\u0633\u06ce\u0646 \u0698 \u0628\u06c6\u062a\u06cc \u0628 \u0646\u0627\u06a4\u06ce "+a+" \u062f\u0647\u06ce\u0646\u06d5 \u062a\u06c6\u0645\u0627\u0631\u06a9\u0631\u0646."},
gakG(){return"\u0698\u06ce\u06a4\u06d5\u06a9\u0631\u0646\u0627 \u0628\u06c6\u062a\u06cc"},
gakI(){return"\u0628\u06c6\u062a \u0628\u0647\u06ce\u062a\u06d5 \u0698\u06ce\u06a4\u06d5\u06a9\u0631\u0646\u061f"},
akH(a){return a+" \u062f\u06ce \u0686\u06cc\u062f\u06cc \u0628\u06d5\u0631\u0633\u06a4\u06ce \u0646\u06d5\u062f\u06d5\u062a \u0648 \u06af\u0631\u06ce\u062f\u0627\u0646\u0627 \u0647\u06d5\u0645\u06cc \u062f\u06a9\u062a\u06c6\u0631\u0627\u0646 \u062f\u06ce \u0647\u06ce\u062a\u06d5 \u0698\u06ce\u0628\u0631\u0646. \u0626\u06d5\u0648 \u06a9\u06d5\u06cc\u0633\u06ce\u0646 \u0628\u06d5\u0631\u06cc \u0646\u0648\u06a9\u06d5 \u0647\u0627\u062a\u06cc\u0646\u06d5 \u0641\u0631\u06ce\u06a9\u0631\u0646 \u0644 IQ Labs \u062f\u0645\u06cc\u0646\u0646."},
gHI(){return"\u0632\u06ce\u062f\u06d5\u06a9\u0631\u0646\u0627 \u067e\u06c6\u0644\u06ce"},
